supportingTypes.declaration:
export interface AccordionItem {
  id: string;
  title: string;
  content: ReactNode;
  disabled?: boolean;
}

export interface BreadcrumbItem {
  label: string;
  href?: string;
}

export interface FieldControlProps {
  id: string;
  "aria-describedby": string | undefined;
  "aria-invalid": true | undefined;
  disabled: boolean;
  required: boolean;
  invalid: boolean;
}

export interface NativeSelectOption {
  value: string;
  label: string;
  disabled?: boolean;
}

export interface NavItem {
  href: string;
  label: string;
  current?: boolean;
}

export interface RadioItem {
  value: string;
  label: string;
  description?: string;
  disabled?: boolean;
}

export interface SelectOption {
  /** Unique, nonempty form value. */
  value: string;
  label: string;
  disabled?: boolean;
}

export interface TabItem {
  id: string;
  label: string;
  content: ReactNode;
  disabled?: boolean;
}

export interface ToggleGroupItem {
  id: string;
  label: string;
  icon?: ReactNode;
  disabled?: boolean;
}
